<script>(()=>{const form=document.getElementById('rt-bulk'),button=document.querySelector('button[form="rt-bulk"]'),dialog=document.getElementById('rt-bulk-confirm'),count=dialog?.querySelector('[data-rt-count]');if(!form||!button||!dialog)return;const boxes=[...document.querySelectorAll('input[name="sample_ids[]"]')];boxes.forEach(box=>{const status=box.closest('tr')?.querySelector('.rt-badge')?.textContent.trim();if(status==='AGUARDANDO RESULTADO')box.disabled=false});const sync=()=>{const total=boxes.filter(box=>box.checked&&!box.disabled).length;button.disabled=total===0;if(count)count.textContent=String(total)};boxes.forEach(box=>box.addEventListener('change',sync));button.type='button';button.addEventListener('click',()=>{sync();if(!button.disabled)dialog.showModal()});dialog.querySelector('[data-rt-cancel]')?.addEventListener('click',()=>dialog.close());sync()})();</script>
<script>(()=>{document.querySelectorAll('[data-open]').forEach(b=>b.addEventListener('click',()=>{const row=document.querySelector(`[data-form="${b.dataset.open}"]`);row.hidden=!row.hidden;b.textContent=row.hidden?'Abrir':'Fechar'}));document.querySelectorAll('[data-rt-result]').forEach(form=>{const select=form.querySelector('select[name="result"]'),wrap=form.querySelector('[data-bacteria]'),input=wrap?.querySelector('input');if(!select||!wrap)return;const sync=()=>{const positive=select.value==='positive';wrap.hidden=!positive;if(input){input.required=positive;if(!positive)input.value=''}};select.addEventListener('change',sync);sync()})})();</script>
